/* Orthographic 3D geometry shared by the pallet editor and vehicle view. Units: mm. */
(function(root){
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function camera(degrees=35){const a=degrees*Math.PI/180,c=Math.cos(a),s=Math.sin(a),tilt=.52;return {project(x,y,z=0){return {x:c*x-s*y,y:tilt*(s*x+c*y)-z};},unproject(u,v,z=0){const q=(v+z)/tilt;return {x:c*u+s*q,y:-s*u+c*q};},depth(x,y,z){return s*x+c*y+tilt*z;},c,s};}
function vertices(b){return [[b.x,b.y,b.z],[b.x+b.w,b.y,b.z],[b.x+b.w,b.y+b.d,b.z],[b.x,b.y+b.d,b.z],[b.x,b.y,b.z+b.h],[b.x+b.w,b.y,b.z+b.h],[b.x+b.w,b.y+b.d,b.z+b.h],[b.x,b.y+b.d,b.z+b.h]];}
function scene(boxes,{angle=35,wire=null}={}){const cam=camera(angle),faces=[],all=[],labels=[];for(const b of boxes){const vs=vertices(b),ps=vs.map(p=>cam.project(...p));all.push(...ps);const sets=[{v:[4,5,6,7],shade:1},{v:cam.s>=0?[3,2,6,7]:[0,1,5,4],shade:.83},{v:cam.c>=0?[1,2,6,5]:[0,3,7,4],shade:.68}];for(const f of sets){const center=f.v.reduce((r,i)=>r.map((v,k)=>v+vs[i][k]/4),[0,0,0]);faces.push({b,f,ps,depth:cam.depth(...center)});}if(b.label){const p=cam.project(b.x+b.w/2,b.y+b.d/2,b.z+b.h);labels.push({b,p});}}
faces.sort((a,b)=>(a.b.background??0)-(b.b.background??0)||a.depth-b.depth);let html=faces.map(({b,f,ps})=>{const colour=b.color||'#b6cda0',hex=colour.slice(1),rgb=[0,2,4].map(i=>Math.round(parseInt(hex.slice(i,i+2),16)*f.shade));return `<polygon ${b.id?`data-box="${escape(b.id)}"`:''} points="${f.v.map(i=>ps[i].x+','+ps[i].y).join(' ')}" fill="rgb(${rgb.join(',')})" stroke="${b.selected?'#0a4d78':'#4c5d46'}" stroke-width="${b.selected?7:2}" opacity="${b.opacity??1}" vector-effect="non-scaling-stroke"><title>${escape(b.title||b.label||'')}</title></polygon>`;}).join('');
for(const {b,p}of labels)html+=`<text pointer-events="none" x="${p.x}" y="${p.y}" text-anchor="middle" font-size="${Math.max(25,Math.min(75,b.w/Math.max(String(b.label).length,5)))}" fill="#193b2c" paint-order="stroke" stroke="#fff" stroke-width="2">${escape(b.label)}</text>`;
if(wire){const ps=vertices(wire).map(p=>cam.project(...p));all.push(...ps);html+=`<g fill="none" stroke="#507567" stroke-width="2" stroke-dasharray="8 5" vector-effect="non-scaling-stroke" pointer-events="none">${[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]].map(([a,b])=>`<path d="M${ps[a].x},${ps[a].y}L${ps[b].x},${ps[b].y}"/>`).join('')}</g>`;}
if(!all.length)all.push({x:0,y:0},{x:1000,y:1000});const minX=Math.min(...all.map(p=>p.x)),maxX=Math.max(...all.map(p=>p.x)),minY=Math.min(...all.map(p=>p.y)),maxY=Math.max(...all.map(p=>p.y)),pad=Math.max(maxX-minX,maxY-minY)*.08+50;return {html,viewBox:`${minX-pad} ${minY-pad} ${maxX-minX+pad*2} ${maxY-minY+pad*2}`};}
function palletBoxes(t,selected=null,active=null){const heights=Array.from({length:t.layerCount},(_,i)=>Math.max(0,...t.boxes.filter(b=>b.layer===i).map(b=>b.h))),bottom=heights.map((_,i)=>t.palletHeight+heights.slice(0,i).reduce((a,b)=>a+b,0));return [{x:0,y:0,z:0,w:t.L,d:t.D,h:t.palletHeight,background:-1,color:'#b49a6e',title:'Pallet base'},...t.boxes.map(b=>({...b,z:bottom[b.layer],color:b.invalid?'#e39c88':'#b6cda0',selected:b.id===selected,opacity:active===null||b.layer===active?1:.4,label:b.model,title:`${b.model}: ${b.w/10} × ${b.d/10} × ${b.h/10} cm · layer ${b.layer+1}`}))];}
function arrange(w,d,n,L,D){if(!Number.isInteger(n)||n<1||n>30)throw Error('Choose 1 to 30 cartons.');const candidates=[];for(const rotated of [false,true])for(let cols=1;cols<=n;cols++){const bw=rotated?d:w,bd=rotated?w:d,rows=Math.ceil(n/cols),W=cols*bw,H=rows*bd;const overflow=Math.max(0,W-L)+Math.max(0,H-D),empty=rows*cols-n;candidates.push({rotated,cols,rows,bw,bd,W,H,score:overflow*100000+empty*1000+Math.abs(W/L-H/D)});}candidates.sort((a,b)=>a.score-b.score);const c=candidates[0];return Array.from({length:n},(_,i)=>({x:(L-c.W)/2+(i%c.cols)*c.bw,y:(D-c.H)/2+Math.floor(i/c.cols)*c.bd,w:c.bw,d:c.bd}));}
function truckBoxes(trip){const boxes=[];for(const p of trip.placements){if(p.layout){const t=p.layout,base=t.pallet,local=palletBoxes({L:base.L,D:base.D,palletHeight:base.height,layerCount:p.layers,boxes:t.boxes});for(const b of local){let x=b.x-t.footprint.minX,y=b.y-t.footprint.minY,w=b.w,d=b.d;if(p.rotated){[x,y,w,d]=[y,p.L-x-w,d,w];}boxes.push({...b,id:undefined,label:undefined,x:p.x+x,y:p.y+y,w,d,title:`Pallet ${p.loadOrder} · ${b.title||b.model||''}`});}boxes.push({x:p.x,y:p.y,z:p.H+2,w:p.w,d:p.d,h:1,color:'#b6cda0',opacity:0,label:String(p.loadOrder)});}else{boxes.push({x:p.x,y:p.y,z:0,w:p.w,d:p.d,h:p.H,color:'#adc4a1',label:String(p.loadOrder),title:`${p.model} · ${p.quantity} cartons · ${p.layers} layers`});}}return boxes;}
root.LoadScene3D={camera,scene,palletBoxes,arrange,truckBoxes};if(typeof module!=='undefined')module.exports=root.LoadScene3D;
})(typeof globalThis!=='undefined'?globalThis:window);
